const list=$('#reward-list'),search=$('#reward-search');
const raftChoices=new Map();let selectedReward=null;
function rewardName(r){return fmt(r.amount)+' '+r.name;}
function renderRewards(){const q=(search?.value||'').toLowerCase().trim(),matches=data.rewards.filter(m=>(fmt(m.threshold)+' '+m.threshold+' '+m.items.map(rewardName).join(' ')).toLowerCase().includes(q));list.replaceChildren();for(const m of matches){const row=document.createElement('div');row.className='reward-entry';const target=document.createElement('strong');target.textContent=fmt(m.threshold)+(data.unit?' '+data.unit:'');const items=document.createElement('div');{target.className='fish-milestone';const coin=document.createElement('img'),number=document.createElement('span');coin.src=page==='fishing'?'/guide-assets/fishing/silvercoin.png':page==='cozy-farm'?'/guide-assets/cozy-farm/weight.png':page==='raft-race'?'/assets/raftrace.png':page==='zobo-shooter'?'/assets/zoboshooter.png':'/assets/treasurehunt.png';coin.alt=page==='fishing'?'Silver coins':'Progress';number.textContent=fmt(m.threshold)+(page==='fishing'||page==='zobo-shooter'?'':' '+(data.unit||''));target.replaceChildren(coin,number);items.className='fish-reward-items';for(const r of m.items){const item=document.createElement('span');item.className='fish-reward-item';if(r.icon){const icon=document.createElement('img');icon.src=r.icon;icon.alt='';item.append(icon);}const amount=document.createElement('b'),name=document.createElement('span');amount.textContent=r.type===12&&r.id===110005002?'Lv '+r.amount:fmt(r.amount);name.textContent=r.type===12&&r.id===110005002?'Fishing Rod':r.name;item.append(amount,name);items.append(item);}}row.append(target,items);if(page==='raft-race')addRaftOptions(m,row);if($('#reward-total')){row.tabIndex=0;row.setAttribute('role','button');row.setAttribute('aria-label','Total rewards through '+fmt(m.threshold));row.setAttribute('aria-pressed','false');const choose=()=>showFarmRewardTotal(m,row);row.addEventListener('click',choose);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}});}list.append(row);}if(!matches.length)list.textContent='No matching milestones. Try a reward name or threshold.';}
if(list){search?.addEventListener('input',renderRewards);renderRewards();}

if(page==='cozy-farm'){const select=$('#crop-stage-choice'),gallery=$('#crop-stage-gallery');for(const crop of data.crops)select.add(new Option(crop.name,crop.id));function paintStages(){const crop=data.crops.find(c=>c.id===Number(select.value));gallery.replaceChildren();crop.stages.forEach((src,i)=>{const figure=document.createElement('figure'),image=document.createElement('img'),caption=document.createElement('figcaption');image.src=src;image.alt=crop.name+' stage '+(i+1);caption.textContent=i===3?'Stage 4-5':'Stage '+(i+1);const art=document.createElement('div');art.className='tree-art';const dimensions=crop.stage_geometry;const scale=110/Math.max(...dimensions.map(g=>Math.max(g.bounds[2]-g.bounds[0],g.bounds[3]-g.bounds[1])));const g=dimensions[i];image.style.width=(g.size[0]*scale)+'px';image.style.height=(g.size[1]*scale)+'px';image.style.left='calc(50% - '+((g.bounds[0]+g.bounds[2])/2*scale)+'px)';image.style.top=(110-g.bounds[3]*scale)+'px';art.append(image);figure.append(art,caption);gallery.append(figure);});}select.onchange=paintStages;paintStages();}

function showFarmRewardTotal(m,row,source=data.rewards,box=$('#reward-total'),container=list,label=null){
 if(container===list)selectedReward={m,row};const totals=new Map();
 for(const milestone of source.filter(r=>r.threshold<=m.threshold))for(const item of resolvedMilestoneItems(milestone)){const key=page==='raft-race'&&item.type===18?'unselected-chests':item.type+':'+item.id;if(!totals.has(key))totals.set(key,{...item,amount:0});if(item.type===12&&item.id===110005002)totals.get(key).amount=Math.max(totals.get(key).amount,item.amount);else totals.get(key).amount+=item.amount;}
 for(const entry of container.children){entry.classList.toggle('selected',entry===row);entry.setAttribute('aria-pressed',String(entry===row));}
 box.replaceChildren();const title=document.createElement('strong');title.textContent=label||('Total rewards through '+fmt(m.threshold)+(page==='zobo-shooter'?'':' '+(data.unit||'')));box.append(title);
 const items=document.createElement('div');items.className='fish-reward-items';for(const item of totals.values()){const span=document.createElement('span');span.className='fish-reward-item';if(item.icon){const img=document.createElement('img');img.src=item.icon;img.alt='';span.append(img);}const amount=document.createElement('b');amount.textContent=item.type===12&&item.id===110005002?'Lv '+item.amount:fmt(item.amount);span.append(amount,document.createTextNode(' '+item.name));items.append(span);}box.append(items);
}

if(page==='treasure-hunt'){
 const chestList=$('#chest-list');data.chests.forEach((chest,i)=>{const row=document.createElement('div');row.className='reward-entry';row.tabIndex=0;row.setAttribute('role','button');row.setAttribute('aria-pressed','false');const target=document.createElement('strong');target.className='fish-milestone';const key=document.createElement('img');key.src='/guide-assets/rewards/12-110003002.png';key.alt='Keys';const chestIcon=document.createElement('img');chestIcon.src=['/guide-assets/treasure-hunt/chest1.png','/guide-assets/treasure-hunt/chest2.png','/guide-assets/treasure-hunt/chest3.png'][Math.min(i,2)];chestIcon.alt='';const label=document.createElement('b');label.textContent='Chest '+(i+1);const count=document.createElement('b');count.textContent='· '+chest.threshold;target.append(chestIcon,label,count,key);const items=document.createElement('div');items.className='fish-reward-items';for(const item of chest.items){const span=document.createElement('span');span.className='fish-reward-item';const icon=document.createElement('img');icon.src=item.icon;icon.alt='';const amount=document.createElement('b');amount.textContent=fmt(item.amount);span.append(icon,amount,document.createTextNode(' '+item.name));items.append(span);}row.append(target,items);const choose=()=>showFarmRewardTotal(chest,row,data.chests,$('#chest-total'),chestList,'Total rewards through Chest '+(i+1));row.addEventListener('click',choose);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}});chestList.append(row);});
}

function resolvedMilestoneItems(m){return m.items.map(item=>{if(page!=='raft-race'||item.type!==18)return item;const chosen=raftChoices.get(m.threshold+':'+item.id);if(chosen===undefined)return item;const option=data.choice_boxes.find(b=>b.id===item.id).options[chosen];return {...option,amount:option.amount*item.amount};});}
function addRaftOptions(m,row){for(const item of m.items.filter(r=>r.type===18)){const box=data.choice_boxes.find(b=>b.id===item.id);if(!box)continue;const group=document.createElement('div');group.className='raft-options';group.setAttribute('role','group');group.setAttribute('aria-label','Choose chest reward at '+m.threshold);box.options.forEach((option,i)=>{const button=document.createElement('button');button.type='button';button.setAttribute('aria-pressed','false');const label=document.createElement('b');label.textContent='Opt '+String.fromCharCode(65+i);button.append(label);if(option.icon){const img=document.createElement('img');img.src=option.icon;img.alt='';button.append(img);}button.append(document.createTextNode(fmt(option.amount*item.amount)+' '+option.name));button.addEventListener('click',e=>{e.stopPropagation();const key=m.threshold+':'+item.id;if(raftChoices.get(key)===i)raftChoices.delete(key);else raftChoices.set(key,i);[...group.children].forEach((b,j)=>b.setAttribute('aria-pressed',String(raftChoices.get(key)===j)));if(selectedReward)showFarmRewardTotal(selectedReward.m,selectedReward.row);else showFarmRewardTotal(m,row);});group.append(button);});row.append(group);}}
